1	#ifndef GROKKING_KERNELS_SM90_SUPERGROK11_SM90_CUH_
2	#define GROKKING_KERNELS_SM90_SUPERGROK11_SM90_CUH_
3	// ============================================================================
4	// supergrok11_sm90.cuh — CANONICAL SuperGrok sm_90 device kernels for 'supergrok11'.
5	//
6	// This header is the SINGLE source of truth for the sm_90 device logic:
7	// templated __forceinline__ __device__ update/_vec4 functions, the __global__
8	// launcher kernels, every inline-PTX (asm-volatile) block VERBATIM, and (for
9	// muon/supergrok2) the CUTLASS Sm90 tensor-core collectives. It is a
10	// composition primitive for the future fused megakernel.
11	//
12	// The production TU csrc/backends/cuda/sm_90/launch_supergrok11.cu now #include's
13	// this header and keeps only the host launcher(s) the pybind layer calls.
14	// Migrated byte-for-byte from that .cu; verified compile-neutral via the
15	// preprocessor-equivalence gate (nvcc -E, modulo __FILE__).
16	// ============================================================================
17	// CUDA sm_90 launch glue for SuperGrok v1.1.
18	// Algorithm: csrc/algorithms/supergrok11.h
19	//
20	// Two-sweep cooperative pattern:
21	//   Sweep A: meta-net forward + cosine gate reduction
22	//   Sweep B: smart_grad mixing + Adam apply (uses gate from sweep A)
23	//
24	// The meta-net hidden width H is fixed at compile time. Defaults to 64.
25	
26	#include <torch/extension.h>
27	#include <ATen/cuda/CUDAContext.h>
28	
29	#include "csrc/algorithms/supergrok11.h"
30	// ── Autotuner-consumable launch parameters (inlined; see compile.py) ──
31	#ifndef SG_TUNED_BLOCK_SIZE
32	#define SG_TUNED_BLOCK_SIZE 256
33	#endif
34	#ifndef SG_TUNED_VEC_WIDTH
35	#define SG_TUNED_VEC_WIDTH 4
36	#endif
37	#ifndef SG_TUNED_UNROLL
38	#define SG_TUNED_UNROLL 1
39	#endif
40	#ifndef SG_TUNED_ASYNC_DEPTH
41	#define SG_TUNED_ASYNC_DEPTH 2
42	#endif
43	#include "csrc/backends/cuda/sm_90/primitives.cuh"
44	#include "grokking_optimizers/kernels/sm_90/common_sm90.cuh"
45	
46	namespace sg { namespace sm90 {
47	
48	namespace prim = ::sg::sm90::primitives;
49	using ::sg::algorithms::sg11_phi_forward;
50	using ::sg::algorithms::sg11_sweep_a_step;
51	using ::sg::algorithms::sg11_sweep_b_step;
52	using ::sg::algorithms::sg11_adam_tail;
53	
54	constexpr int SG11_H = 64;
55	
56	// Minimum resident blocks/SM for the element-wise sweeps. Caps registers so
57	// occupancy stays high on the (memory-bound) Adam apply.
58	#ifndef SG_SUPERGROK11_MIN_BLOCKS
59	#define SG_SUPERGROK11_MIN_BLOCKS 4
60	#endif
61	
62	// Cooperatively stage the per-element meta-net phi weights into shared memory
63	// ONCE per block, then hand the shared pointers to the canonical
64	// sg11_phi_forward<H>. W1 is [H,2] (row-major, 2 inputs/hidden unit), b1/W2 are
65	// [H]. The same weights are read by every element this block processes; staging
66	// removes the per-element re-read from GLOBAL inside the H-wide forward loop. NO
67	// math/signature change — the fn still takes const float* (single-sourced in
68	// algorithms/supergrok11.h).
69	template <int H>
70	__device__ __forceinline__ void sg11_stage_phi_weights(
71	    const float* __restrict__ W1, const float* __restrict__ b1,
72	    const float* __restrict__ W2,
73	    float* sW1, float* sb1, float* sW2
74	) {
75	    for (int j = threadIdx.x; j < H * 2; j += blockDim.x) sW1[j] = W1[j];
76	    for (int j = threadIdx.x; j < H;     j += blockDim.x) { sb1[j] = b1[j]; sW2[j] = W2[j]; }
77	    __syncthreads();
78	}
79	
80	template <typename GradT>
81	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
82	sg11_sweep_a_kernel(
83	    float* mu_out, const GradT* grad, const float* sharpness, const float* momentum,
84	    const float* W1, const float* b1, const float* W2, float b2,
85	    float* gate_num_p, float* gate_den_g_p, float* gate_den_m_p,
86	    int64_t N
87	) {
88	    __shared__ float sW1[SG11_H * 2];
89	    __shared__ float sb1[SG11_H];
90	    __shared__ float sW2[SG11_H];
91	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
92	
93	    float gn = 0.0f, gdg = 0.0f, gdm = 0.0f;
94	    const int64_t stride = prim::grid_stride();
95	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
96	        SG_SANITIZE_GRAD_INPLACE(grad, i);
97	        const float g = static_cast<float>(grad[i]);
98	        const float s = sharpness[i];
99	        const float mu_val = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2);
100	        sg11_sweep_a_step(mu_out, grad, sharpness, momentum, mu_val, i,
101	                          gn, gdg, gdm);
102	    }
103	    float r1 = prim::block_reduce_sum_f32(gn);
104	    float r2 = prim::block_reduce_sum_f32(gdg);
105	    float r3 = prim::block_reduce_sum_f32(gdm);
106	    if (threadIdx.x == 0) {
107	        atomicAdd(gate_num_p, r1);
108	        atomicAdd(gate_den_g_p, r2);
109	        atomicAdd(gate_den_m_p, r3);
110	    }
111	}
112	
113	template <typename ParamT, typename GradT, int UNROLL>
114	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
115	sg11_sweep_b_kernel(
116	    ParamT* param, float* exp_avg, float* exp_avg_sq,
117	    const GradT* grad, const float* mu, float gate,
118	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
119	    float bc1, float bc2, int64_t N
120	) {
121	    const int64_t stride = prim::grid_stride() * UNROLL;
122	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
123	    for (int64_t base = base0; base < N; base += stride) {
124	        #pragma unroll
125	        for (int u = 0; u < UNROLL; ++u) {
126	            const int64_t i = base + u;
127	            if (i < N) {
128	                SG_SANITIZE_GRAD_INPLACE(grad, i);
129	                sg11_sweep_b_step(param, exp_avg, exp_avg_sq, grad, mu, gate,
130	                                  alpha, lr, beta1, beta2, eps, wd, bc1, bc2, i);
131	            }
132	        }
133	    }
134	}
135	
136	// FP32 vec4 sweep B: float4 traffic on param/state/grad/mu, canonical
137	// sg11_sweep_b_step CALLED 4× on the register lanes. Math is NOT re-typed here.
138	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
139	sg11_sweep_b_kernel_vec4_fp32(
140	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
141	    const float4* grad4, const float4* mu4, float gate,
142	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
143	    float bc1, float bc2, int64_t N4
144	) {
145	    const int64_t stride = prim::grid_stride();
146	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
147	        float4 p  = prim::ld_f32v4(param4 + i);
148	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
149	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
150	        float4 g  = prim::ldg_f32v4(grad4 + i);
151	        float4 mu = prim::ldg_f32v4(mu4 + i);
152	        ::grokking::sm90::sg_sanitize_grad4(g);
153	        #pragma unroll
154	        for (int u = 0; u < 4; ++u) {
155	            sg11_sweep_b_step(&p.x, &m.x, &v.x, &g.x, &mu.x, gate,
156	                              alpha, lr, beta1, beta2, eps, wd, bc1, bc2, u);
157	        }
158	        prim::st_f32v4(param4 + i, p);
159	        prim::st_f32v4(exp_avg4 + i, m);
160	        prim::st_f32v4(exp_avg_sq4 + i, v);
161	    }
162	}
