164	void launch_supergrok11_step(
165	    torch::Tensor& param,
166	    torch::Tensor& exp_avg,
167	    torch::Tensor& exp_avg_sq,
168	    torch::Tensor& mu_buf,
169	    const torch::Tensor& grad,
170	    const torch::Tensor& sharpness,
171	    const torch::Tensor& momentum,
172	    const torch::Tensor& phi_W1,
173	    const torch::Tensor& phi_b1,
174	    const torch::Tensor& phi_W2,
175	    float phi_b2,
176	    torch::Tensor& gate_partials,  // [3] {num, den_g, den_m}
177	    float alpha,
178	    float lr, float beta1, float beta2, float eps, float wd,
179	    float bc1, float bc2
180	) {
181	    const int64_t N = param.numel();
182	    if (N == 0) return;
183	
184	    auto stream = at::cuda::getCurrentCUDAStream().stream();
185	
186	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
187	    prim::L2PersistScope l2(stream,
188	        exp_avg.data_ptr(), exp_avg.nbytes(),
189	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
190	
191	    const int block = SG_TUNED_BLOCK_SIZE;
192	    const int grid = static_cast<int>(
193	        std::min<int64_t>(65535, (N + block - 1) / block));
194	
195	    gate_partials.zero_();
196	
197	    AT_DISPATCH_FLOATING_TYPES_AND2(
198	        at::ScalarType::Half, at::ScalarType::BFloat16,
199	        grad.scalar_type(), "sg11_sweep_a", [&] {
200	            sg11_sweep_a_kernel<scalar_t><<<grid, block, 0, stream>>>(
201	                mu_buf.data_ptr<float>(),
202	                grad.data_ptr<scalar_t>(),
203	                sharpness.data_ptr<float>(),
204	                momentum.data_ptr<float>(),
205	                phi_W1.data_ptr<float>(),
206	                phi_b1.data_ptr<float>(),
207	                phi_W2.data_ptr<float>(),
208	                phi_b2,
209	                gate_partials.data_ptr<float>(),
210	                gate_partials.data_ptr<float>() + 1,
211	                gate_partials.data_ptr<float>() + 2,
212	                N);
213	            SG_LAUNCH_CHECK(stream);
214	        });
215	
216	    // Host-side reduction of the 3 scalars and gate clamp.
217	    auto partials_cpu = gate_partials.to(torch::kCPU);
218	    float gn  = partials_cpu[0].item<float>();
219	    float gdg = partials_cpu[1].item<float>();
220	    float gdm = partials_cpu[2].item<float>();
221	    float denom = sqrtf(gdg * gdm + 1e-12f);
222	    float gate = (denom > 0.0f) ? (gn / denom) : 0.0f;
223	    gate = fminf(fmaxf(gate, 0.0f), 1.0f);
224	
225	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
226	                          grad.scalar_type() == torch::kFloat32;
227	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
228	        prim::is_vec4_alignable(param.data_ptr(), N) &&
229	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
230	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
231	        prim::is_vec4_alignable(grad.data_ptr(), N) &&
232	        prim::is_vec4_alignable(mu_buf.data_ptr(), N)) {
233	        const int64_t N4 = N / 4;
234	        const int grid4 = static_cast<int>(
235	            std::min<int64_t>(65535, (N4 + block - 1) / block));
236	        sg11_sweep_b_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
237	            reinterpret_cast<float4*>(param.data_ptr<float>()),
238	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
239	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
240	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
241	            reinterpret_cast<const float4*>(mu_buf.data_ptr<float>()),
242	            gate, alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
243	        SG_LAUNCH_CHECK(stream);
244	        return;
245	    }
246	
247	    AT_DISPATCH_FLOATING_TYPES_AND2(
248	        at::ScalarType::Half, at::ScalarType::BFloat16,
249	        param.scalar_type(), "sg11_sweep_b", [&] {
250	            sg11_sweep_b_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
251	                <<<grid, block, 0, stream>>>(
252	                param.data_ptr<scalar_t>(),
253	                exp_avg.data_ptr<float>(),
254	                exp_avg_sq.data_ptr<float>(),
255	                grad.data_ptr<scalar_t>(),
256	                mu_buf.data_ptr<float>(),
257	                gate, alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N);
258	            SG_LAUNCH_CHECK(stream);
259	        });
260	}
261	
262	
263	// Meta-net forward: mu[i] = phi(grad[i], sharpness[i]); smart_grad = grad + alpha*mu
264	template <typename GradT>
265	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
266	sg11_mu_metanet_kernel(
267	    float* mu, const GradT* grad, const float* sharpness,
268	    float* smart_grad, float alpha,
269	    const float* W1, const float* b1, const float* W2, float b2_scalar,
270	    float rescale, int64_t N
271	) {
272	    __shared__ float sW1[SG11_H * 2];
273	    __shared__ float sb1[SG11_H];
274	    __shared__ float sW2[SG11_H];
275	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
276	
277	    const int64_t stride = prim::grid_stride();
278	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
279	        SG_SANITIZE_GRAD_INPLACE(grad, i);
280	        float g = static_cast<float>(grad[i]);
281	        float s = sharpness[i];
282	        float phi = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2_scalar) * rescale;
283	        mu[i] = phi;
284	        smart_grad[i] = g + alpha * phi;
285	    }
286	}
287	
288	void launch_sg11_mu_metanet(
289	    torch::Tensor mu, torch::Tensor grad, torch::Tensor sharpness,
290	    torch::Tensor smart_grad, float alpha,
291	    torch::Tensor W1, torch::Tensor b1, torch::Tensor W2, torch::Tensor b2,
292	    float rescale, int hidden_dim
293	) {
294	    const int64_t N = mu.numel();
295	    if (N == 0) return;
296	    auto stream = at::cuda::getCurrentCUDAStream().stream();
297	    const int block = SG_TUNED_BLOCK_SIZE;
298	    const int grid = static_cast<int>(
299	        std::min<int64_t>(65535, (N + block - 1) / block));
300	    float b2_val = b2.item<float>();
301	
302	    AT_DISPATCH_FLOATING_TYPES_AND2(
303	        at::ScalarType::Half, at::ScalarType::BFloat16,
304	        grad.scalar_type(), "sg11_mu_metanet", [&] {
305	            sg11_mu_metanet_kernel<scalar_t><<<grid, block, 0, stream>>>(
306	                mu.data_ptr<float>(),
307	                grad.data_ptr<scalar_t>(),
308	                sharpness.data_ptr<float>(),
309	                smart_grad.data_ptr<float>(), alpha,
310	                W1.data_ptr<float>(), b1.data_ptr<float>(),
311	                W2.data_ptr<float>(), b2_val, rescale, N);
312	            SG_LAUNCH_CHECK(stream);
313	        });
314	}
315	
316	// Adam + decoupled WD on smart_grad, with optional lamb-scaled mu blending.
317	__global__ void sg11_adam_decay_kernel(
318	    float* param, float* exp_avg, float* exp_avg_sq,
319	    const float* smart_grad, const float* mu,
320	    float lamb_eff, float beta1, float beta2, float lr,
321	    float wd_eff, float eps, float bc1, float bc2, int64_t N
322	) {
323	    const int64_t stride = prim::grid_stride();
324	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
325	        // g_eff = smart_grad + lamb_eff*mu blending; the bias-corrected Adam +
326	        // decoupled-WD math lives once in algorithms/supergrok11.h.
327	        const float g_eff = ::grokking::sm90::sg_sanitize_grad(smart_grad[i]) +
328	                            lamb_eff * mu[i];
329	        sg11_adam_tail(param, exp_avg, exp_avg_sq, g_eff,
330	                       lr, beta1, beta2, eps, wd_eff, bc1, bc2, i);
331	    }
332	}
333	
334	void launch_sg11_adam_decay(
335	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
336	    torch::Tensor smart_grad, torch::Tensor mu,
337	    float lamb_eff, float beta1, float beta2, float lr,
338	    float wd_eff, float eps, float bc1, float bc2
339	) {
340	    const int64_t N = param.numel();
341	    if (N == 0) return;
342	    auto stream = at::cuda::getCurrentCUDAStream().stream();
343	    const int block = SG_TUNED_BLOCK_SIZE;
344	    const int grid = static_cast<int>(
345	        std::min<int64_t>(65535, (N + block - 1) / block));
346	    sg11_adam_decay_kernel<<<grid, block, 0, stream>>>(
347	        param.data_ptr<float>(), exp_avg.data_ptr<float>(),
348	        exp_avg_sq.data_ptr<float>(),
349	        smart_grad.data_ptr<float>(), mu.data_ptr<float>(),
350	        lamb_eff, beta1, beta2, lr, wd_eff, eps, bc1, bc2, N);
351	    SG_LAUNCH_CHECK(stream);
352	}
