354	// SAM perturbation: param += rho_over_norm * grad
355	template <typename ParamT>
356	__global__ void sg11_sam_perturb_kernel(
357	    ParamT* param, const ParamT* grad, float rho_over_norm, int64_t N
358	) {
359	    const int64_t stride = prim::grid_stride();
360	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
361	        float p = static_cast<float>(param[i]);
362	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
363	        param[i] = static_cast<ParamT>(p + rho_over_norm * g);
364	    }
365	}
366	
367	void launch_sg11_sam_perturb(
368	    torch::Tensor param, torch::Tensor grad, float rho_over_norm
369	) {
370	    const int64_t N = param.numel();
371	    if (N == 0) return;
372	    auto stream = at::cuda::getCurrentCUDAStream().stream();
373	    const int block = SG_TUNED_BLOCK_SIZE;
374	    const int grid = static_cast<int>(
375	        std::min<int64_t>(65535, (N + block - 1) / block));
376	    AT_DISPATCH_FLOATING_TYPES_AND2(
377	        at::ScalarType::Half, at::ScalarType::BFloat16,
378	        param.scalar_type(), "sg11_sam_perturb", [&] {
379	            sg11_sam_perturb_kernel<scalar_t><<<grid, block, 0, stream>>>(
380	                param.data_ptr<scalar_t>(), grad.data_ptr<scalar_t>(),
381	                rho_over_norm, N);
382	            SG_LAUNCH_CHECK(stream);
383	        });
384	}
