386	// Sharpness restore: param = backup, sharpness = ||sam_grad - normal_grad||
387	template <typename ParamT>
388	__global__ void sg11_sharpness_restore_kernel(
389	    ParamT* param, float* sharpness, const ParamT* backup,
390	    const ParamT* sam_grad, const ParamT* normal_grad, int64_t N
391	) {
392	    const int64_t stride = prim::grid_stride();
393	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
394	        param[i] = backup[i];
395	        float sg = static_cast<float>(sam_grad[i]);
396	        float ng = static_cast<float>(normal_grad[i]);
397	        float diff = sg - ng;
398	        sharpness[i] = diff * diff;
399	    }
400	}
401	
402	void launch_sg11_sharpness_restore(
403	    torch::Tensor param, torch::Tensor sharpness, torch::Tensor backup,
404	    torch::Tensor sam_grad, torch::Tensor normal_grad
405	) {
406	    const int64_t N = param.numel();
407	    if (N == 0) return;
408	    auto stream = at::cuda::getCurrentCUDAStream().stream();
409	    const int block = SG_TUNED_BLOCK_SIZE;
410	    const int grid = static_cast<int>(
411	        std::min<int64_t>(65535, (N + block - 1) / block));
412	    AT_DISPATCH_FLOATING_TYPES_AND2(
413	        at::ScalarType::Half, at::ScalarType::BFloat16,
414	        param.scalar_type(), "sg11_sharpness_restore", [&] {
415	            sg11_sharpness_restore_kernel<scalar_t>
416	                <<<grid, block, 0, stream>>>(
417	                param.data_ptr<scalar_t>(),
418	                sharpness.data_ptr<float>(),
419	                backup.data_ptr<scalar_t>(),
420	                sam_grad.data_ptr<scalar_t>(),
421	                normal_grad.data_ptr<scalar_t>(), N);
422	            SG_LAUNCH_CHECK(stream);
423	        });
424	}
