125	// FP32 vec4 sweep B: float4 traffic on param/state/grad/mu, canonical
126	// sg15_sweep_b_step CALLED 4× on the register lanes. Math is NOT re-typed here.
127	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK15_MIN_BLOCKS)
128	sg15_sweep_b_kernel_vec4_fp32(
129	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
130	    const float4* grad4, const float4* mu4,
131	    float gate_global, float alpha_base, float alpha_max,
132	    float lr, float beta1, float beta2, float eps, float wd,
133	    float bc1, float bc2, int64_t N4
134	) {
135	    const int64_t stride = prim::grid_stride();
136	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
137	        float4 p  = prim::ld_f32v4(param4 + i);
138	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
139	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
140	        float4 g  = prim::ldg_f32v4(grad4 + i);
141	        float4 mu = prim::ldg_f32v4(mu4 + i);
142	        ::grokking::sm90::sg_sanitize_grad4(g);
143	        #pragma unroll
144	        for (int u = 0; u < 4; ++u) {
145	            sg15_sweep_b_step(&p.x, &m.x, &v.x, &g.x, &mu.x,
146	                              gate_global, alpha_base, alpha_max,
147	                              lr, beta1, beta2, eps, wd, bc1, bc2, u);
148	        }
149	        prim::st_f32v4(param4 + i, p);
150	        prim::st_f32v4(exp_avg4 + i, m);
151	        prim::st_f32v4(exp_avg_sq4 + i, v);
152	    }
153	}
