155	void launch_supergrok15_step(
156	    torch::Tensor& param,
157	    torch::Tensor& exp_avg,
158	    torch::Tensor& exp_avg_sq,
159	    torch::Tensor& mu_buf,
160	    const torch::Tensor& grad,
161	    const torch::Tensor& sharpness,
162	    const torch::Tensor& phi_W1,
163	    const torch::Tensor& phi_b1,
164	    const torch::Tensor& phi_W2,
165	    float phi_b2,
166	    torch::Tensor& sharp_partial,
167	    float gate_global,
168	    float alpha_base, float alpha_max,
169	    float lr, float beta1, float beta2, float eps, float wd,
170	    float bc1, float bc2
171	) {
172	    const int64_t N = param.numel();
173	    if (N == 0) return;
174	
175	    auto stream = at::cuda::getCurrentCUDAStream().stream();
176	
177	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
178	    prim::L2PersistScope l2(stream,
179	        exp_avg.data_ptr(), exp_avg.nbytes(),
180	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
181	
182	    const int block = SG_TUNED_BLOCK_SIZE;
183	    const int grid = static_cast<int>(
184	        std::min<int64_t>(65535, (N + block - 1) / block));
185	
186	    sharp_partial.zero_();
187	
188	    AT_DISPATCH_FLOATING_TYPES_AND2(
189	        at::ScalarType::Half, at::ScalarType::BFloat16,
190	        grad.scalar_type(), "sg15_sweep_a", [&] {
191	            sg15_sweep_a_kernel<scalar_t><<<grid, block, 0, stream>>>(
192	                mu_buf.data_ptr<float>(),
193	                grad.data_ptr<scalar_t>(),
194	                sharpness.data_ptr<float>(),
195	                phi_W1.data_ptr<float>(),
196	                phi_b1.data_ptr<float>(),
197	                phi_W2.data_ptr<float>(),
198	                phi_b2,
199	                sharp_partial.data_ptr<float>(), N);
200	            SG_LAUNCH_CHECK(stream);
201	        });
202	
203	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
204	                          grad.scalar_type() == torch::kFloat32;
205	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
206	        prim::is_vec4_alignable(param.data_ptr(), N) &&
207	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
208	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
209	        prim::is_vec4_alignable(grad.data_ptr(), N) &&
210	        prim::is_vec4_alignable(mu_buf.data_ptr(), N)) {
211	        const int64_t N4 = N / 4;
212	        const int grid4 = static_cast<int>(
213	            std::min<int64_t>(65535, (N4 + block - 1) / block));
214	        sg15_sweep_b_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
215	            reinterpret_cast<float4*>(param.data_ptr<float>()),
216	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
217	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
218	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
219	            reinterpret_cast<const float4*>(mu_buf.data_ptr<float>()),
220	            gate_global, alpha_base, alpha_max,
221	            lr, beta1, beta2, eps, wd, bc1, bc2, N4);
222	        SG_LAUNCH_CHECK(stream);
223	        return;
224	    }
225	
226	    AT_DISPATCH_FLOATING_TYPES_AND2(
227	        at::ScalarType::Half, at::ScalarType::BFloat16,
228	        param.scalar_type(), "sg15_sweep_b", [&] {
229	            sg15_sweep_b_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
230	                <<<grid, block, 0, stream>>>(
231	                param.data_ptr<scalar_t>(),
232	                exp_avg.data_ptr<float>(),
233	                exp_avg_sq.data_ptr<float>(),
234	                grad.data_ptr<scalar_t>(),
235	                mu_buf.data_ptr<float>(),
236	                gate_global, alpha_base, alpha_max,
237	                lr, beta1, beta2, eps, wd, bc1, bc2, N);
238	            SG_LAUNCH_CHECK(stream);
239	        });
240	}
