243	// Full fused SG15 step: meta-net forward (sweep_a) + Adam update (sweep_b).
244	void launch_fused_supergrok15_full_step(
245	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
246	    torch::Tensor mu, torch::Tensor grad, torch::Tensor sharpness,
247	    float alpha,
248	    torch::Tensor W1, torch::Tensor b1, torch::Tensor W2, torch::Tensor b2,
249	    float rescale, float lamb_eff,
250	    float beta1, float beta2, float lr, float wd_eff, float eps,
251	    float bc1, float bc2, int hidden_dim
252	) {
253	    float b2_val = b2.item<float>();
254	    auto sharp_partial = torch::zeros({1},
255	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
256	    float gate_global = lamb_eff;
257	    float alpha_base = alpha;
258	    float alpha_max = alpha;
259	    launch_supergrok15_step(param, exp_avg, exp_avg_sq, mu, grad, sharpness,
260	                            W1, b1, W2, b2_val, sharp_partial,
261	                            gate_global, alpha_base, alpha_max,
262	                            lr, beta1, beta2, eps, wd_eff, bc1, bc2);
263	}
