265	// SAM perturbation: param += rho_over_norm * grad
266	template <typename ParamT>
267	__global__ void sg15_sam_perturb_kernel(
268	    ParamT* param, const ParamT* grad, float rho_over_norm, int64_t N
269	) {
270	    const int64_t stride = prim::grid_stride();
271	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
272	        float p = static_cast<float>(param[i]);
273	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
274	        param[i] = static_cast<ParamT>(p + rho_over_norm * g);
275	    }
276	}
