297	// Sharpness restore: param = backup, sharpness = (sam_grad - normal_grad)^2
298	template <typename ParamT>
299	__global__ void sg15_sharpness_restore_kernel(
300	    ParamT* param, float* sharpness, const ParamT* backup,
301	    const ParamT* sam_grad, const ParamT* normal_grad, int64_t N
302	) {
303	    const int64_t stride = prim::grid_stride();
304	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
305	        param[i] = backup[i];
306	        float diff = static_cast<float>(sam_grad[i]) -
307	                     static_cast<float>(normal_grad[i]);
308	        sharpness[i] = diff * diff;
309	    }
310	}
