317	    if (N == 0) return;
318	    auto stream = at::cuda::getCurrentCUDAStream().stream();
319	    const int block = SG_TUNED_BLOCK_SIZE;
320	    const int grid = static_cast<int>(
321	        std::min<int64_t>(65535, (N + block - 1) / block));
322	    AT_DISPATCH_FLOATING_TYPES_AND2(
323	        at::ScalarType::Half, at::ScalarType::BFloat16,
324	        param.scalar_type(), "sg15_sharpness_restore", [&] {
325	            sg15_sharpness_restore_kernel<scalar_t>
326	                <<<grid, block, 0, stream>>>(
327	                param.data_ptr<scalar_t>(),
328	                sharpness.data_ptr<float>(),
329	                backup.data_ptr<scalar_t>(),
330	                sam_grad.data_ptr<scalar_t>(),
331	                normal_grad.data_ptr<scalar_t>(), N);
332	            SG_LAUNCH_CHECK(stream);
