1264	// Per-tensor cosine-gate dispatch helper. The arch-namespaced
1265	// compute_cosine_gate_fused is a host-side function that internally
1266	// launches the 3-quantity reduction kernel and does the sigmoid on the
1267	// result. Returns the gate.
1268	static float dispatch_cosine_gate(
1269	 torch::Tensor smart_grad, torch::Tensor mu, float gate_temp)
1270	{
1271	 const int sg_arch_ = ::sg::detect_arch();
1272	 switch (sg_arch_) {
1273	 SG_CASE_SM90_RET(compute_cosine_gate_fused, smart_grad, mu, gate_temp)
