1283	void supergrok11_fused_step(
1284	 std::vector<torch::Tensor>& params,
1285	 std::vector<torch::Tensor>& grads,
1286	 std::vector<torch::Tensor>& exp_avgs,
1287	 std::vector<torch::Tensor>& exp_avg_sqs,
1288	 std::vector<torch::Tensor>& mus,
1289	 std::vector<torch::Tensor>& sharpness_cache,
1290	 std::vector<int64_t>& steps,
1291	 std::vector<float>& layer_alphas,
1292	 std::vector<float>& layer_beta1s,
1293	 torch::Tensor W1, torch::Tensor b1,
1294	 torch::Tensor W2, torch::Tensor b2,
1295	 float rescale, int hidden_dim,
1296	 float beta2, float lr, float wd_eff, float eps,
1297	 float lamb, float ramp, float gate_temperature,
1298	 float grad_clip_norm
1299	) {
1300	 const size_t n_params = params.size();
1301	 check_params_grads(params, grads, "supergrok11_fused_step");
1302	 clip_grad_norms_device_side(grads, n_params, grad_clip_norm);
1303	
1304	 for (size_t i = 0; i < n_params; i++) {
1305	 if (!grads[i].defined() || grads[i].numel() == 0) continue;
1306	 steps[i] += 1;
1307	 float alpha = layer_alphas[i];
1308	 float beta1 = layer_beta1s[i];
1309	 float bc1 = 1.0f - std::pow(beta1, static_cast<float>(steps[i]));
1310	 float bc2 = 1.0f - std::pow(beta2, static_cast<float>(steps[i]));
1311	
1312	 auto smart_grad = torch::empty_like(params[i]);
1313	 SG_DISPATCH_CALL(launch_sg11_mu_metanet,
1314	 mus[i], grads[i], sharpness_cache[i], smart_grad, alpha,
1315	 W1, b1, W2, b2, rescale, hidden_dim);
1316	
1317	 float gate = dispatch_cosine_gate(smart_grad, mus[i], gate_temperature);
1318	 float lamb_eff = (ramp > 0.0f) ? (ramp * gate * lamb) : 0.0f;
1319	
1320	 SG_DISPATCH_CALL(launch_sg11_adam_decay,
1321	 params[i], exp_avgs[i], exp_avg_sqs[i], smart_grad, mus[i],
1322	 lamb_eff, beta1, beta2, lr, wd_eff, eps, bc1, bc2);
1323	 }
1324	}
