1326	// Pre-refactor: SG v1.1 SAM perturb-all reuses v1.5's logic (same math).
1327	std::vector<torch::Tensor> supergrok11_sam_perturb_all(
1328	 std::vector<torch::Tensor>& params,
1329	 std::vector<torch::Tensor>& grads,
1330	 float rho)
1331	{
1332	 float grad_norm = compute_sam_grad_norm_device_side(grads, grads.size());
1333	 float rho_over_norm = rho / grad_norm;
1334	 std::vector<torch::Tensor> backups;
1335	 backups.reserve(params.size());
1336	 for (size_t i = 0; i < params.size(); i++) {
1337	 // Grad-less params are not perturbed; skip the clone and alias the param
1338	 // as its own backup. The restore for these entries (params[i].copy_(
1339	 // backups[i])) is then a self-copy no-op — identical behavior, no clone.
1340	 if (!grads[i].defined() || grads[i].numel() == 0) {
1341	 backups.push_back(params[i]);
1342	 continue;
1343	 }
1344	 backups.push_back(params[i].clone());
1345	 SG_DISPATCH_CALL(launch_sg11_sam_perturb,
1346	 params[i], grads[i], rho_over_norm);
1347	 }
1348	 return backups;
1349	}
